//! Файл: settings/catalog/feed_watch.rs
//! Что делает: настройки сторожа пар и соединений стаканов (решение 202, core/feed_watch.rs). Значений нет; любая не
//! задана у площадки — сторож площадки выключен (причина — в журнале). Советы Тиграна — docs/FIRST_RUN.md.
//! Кто вызывает: settings/catalog/mod.rs.
//! От чего зависит: settings/catalog/mod.rs (короткая запись d и наборы областей).
//! Настройки: это и есть их список (зеркало docs/SETTINGS.md, раздел «Сторож пар»).

use super::{GV, d};
use crate::settings::schema::{Kind as K, Limit as L, SettingDef};

/// Настройки решения 202. Порядок — как в docs/SETTINGS.md.
#[rustfmt::skip]
pub static FEED_WATCH: &[SettingDef] = &[
    d("Сторож пар", "venue.pair_dead_mult", K::Integer, L::Positive, "раз", GV, "Решение 202: пара мёртвая, если при живом соединении (кадр не старше feed.stale_after_ms) по ней нет кадра стакана дольше venue.book_stale_ms × это число. Только у бирж, где кадры стакана идут по расписанию и без изменений (Gate spot.order_book); у остальных тишина — норма, сторожа нет").optional(),
    d("Сторож пар", "venue.feed_warmup_ms", K::Integer, L::Positive, "мс", GV, "Решение 202: прогрев — после начала сессии соединения (старт бота, переподключение) и после переподписки пары она не считается мёртвой столько мс: при ребуте, пока потоки оживают, ничего не дёргается").optional(),
    d("Сторож пар", "venue.pair_resub_attempts", K::Integer, L::Positive, "попыток", GV, "Решение 202: сколько раз подряд переподписать мёртвую пару в одном круге (только её — отписка + подписка, соседи по соединению не трогаются)").optional(),
    d("Сторож пар", "venue.pair_resub_interval_ms", K::Integer, L::Positive, "мс", GV, "Решение 202: промежуток между попытками переподписки пары в круге; с этой же частотой сторож смотрит свежесть пар").optional(),
    d("Сторож пар", "venue.pair_resub_pause_ms", K::Integer, L::Positive, "мс", GV, "Решение 202: пауза после круга попыток, если пара не ожила; потом новый круг").optional(),
    d("Сторож пар", "venue.conn_dead_pct", K::Integer, L::Positive, "%", GV, "Решение 202: если в соединении (пачке пар) мёртвых пар после двух неудачных кругов больше этой доли и по его парам нет идущей сделки — переподключается только это соединение; есть сделка — не переподключается, уведомление venue.feed_conn_blocked").optional(),
    d("Сторож пар", "venue.conn_reconnect_min_ms", K::Integer, L::Positive, "мс", GV, "Решение 202: следующее переподключение того же соединения сторожем — не раньше, чем через столько мс (защита от цикла)").optional(),
    d("Сторож пар", "venue.conn_reconnect_max_per_hour", K::Integer, L::Positive, "раз", GV, "Решение 202: больше стольких переподключений одного соединения за час — больше не переподключаем, журнал и уведомление venue.feed_conn_giveup («нужен человек»)").optional(),
];
